/**
 * Static method to create a shared project, and start a server.
 *
 */
public class SharedProjectUtil {

	public static readonly int SERVER_PORT = ServerTestUtil.GHIDRA_TEST_SERVER_PORT;
	public static string LOCALHOST = ServerTestUtil.LOCALHOST;
	public static readonly string USER = ClientUtil.getUserName();
	
	private static File serverRoot;
	private static RepositoryServerAdapter repositoryServer;

	public static bool createSharedProject(FrontEndTool frontEndTool, string projectName)
    {
		// create shared project against existing repository
		Msg.info(typeof(SharedProjectUtil),
			"SharedProjectUtil.createSharedProject(): " + projectName);

		UtilProjectListener projectListener = new UtilProjectListener();
		frontEndTool.addProjectListener(projectListener);

		DockingActionIf action = getAction(frontEndTool, "New Project");
		AbstractDockingTest.performAction(action, false);
		AbstractGuiTest.waitForSwing();

		WizardDialog wm = AbstractDockingTest.waitForDialogComponent(typeof(WizardDialog));

		ProjectTypePanel typePanel = AbstractDockingTest.findComponent(wm, typeof(ProjectTypePanel));
		JRadioButton rb =
			(JRadioButton) AbstractGuiTest.findAbstractButtonByText(typePanel,
				"Shared Project");

		SwingUtilities.invokeAndWait(() => rb.setSelected(true));

		JButton nextButton = AbstractDockingTest.findButtonByText(wm, "Next >>");
		JButton finishButton = AbstractDockingTest.findButtonByText(wm, "Finish");

		AbstractGuiTest.pressButton(nextButton, true);

		ServerInfoPanel serverPanel = AbstractDockingTest.findComponent(wm, typeof(ServerInfoPanel));

		JTextField serverField =
			(JTextField) AbstractGuiTest.findComponentByName(serverPanel, "Server Name");
		JTextField portNumberField =
			(JTextField) AbstractGuiTest.findComponentByName(serverPanel, "Port Number");

		SwingUtilities.invokeAndWait(() => {
			serverField.setText(LOCALHOST);
			portNumberField.setText(Integer.toString(SERVER_PORT));
		});

		AbstractGuiTest.pressButton(nextButton);

		// next panel should be the repository panel
		RepositoryPanel repPanel = AbstractDockingTest.findComponent(wm, typeof(RepositoryPanel));

		JList<object> repList = AbstractGuiTest.findComponent(repPanel, typeof(JList));

		// select existing repository
		SwingUtilities.invokeAndWait(() => repList.setSelectedIndex(0));

		// next panel is project location panel
		AbstractGuiTest.pressButton(nextButton, true);

		SelectProjectPanel projPanel =
			AbstractDockingTest.findComponent(wm, typeof(SelectProjectPanel));

		string testProjectDirectory = AbstractGTest.getTestDirectoryPath();
		JTextField projDirField =
			(JTextField) AbstractGuiTest.findComponentByName(projPanel, "Project Directory");
		JTextField projNameField =
			(JTextField) AbstractGuiTest.findComponentByName(projPanel, "Project Name");

		SwingUtilities.invokeAndWait(() => {
			projDirField.setText(testProjectDirectory);
			projNameField.setText(projectName);
		});

		assertTrue("Finish button is unexpectedly disabled", finishButton.isEnabled());

		AbstractGuiTest.pressButton(finishButton, true);
		AbstractGuiTest.waitForSwing();
		bool didOpen = waitForProjectToOpen(projectName, projectListener);
		Msg.info(typeof(SharedProjectUtil), "\tdid the project get opened?: " + didOpen);
		return didOpen;
	}

	private static bool waitForProjectToOpen(string desiredProjectName,
			UtilProjectListener projectListener) {
		int waitTime = 100;
		int maxWaits = 150;
		int numWaits = 0;
		string lastOpenedProjectName = projectListener.getLastOpenedProjectName();
		while (!desiredProjectName.equals(lastOpenedProjectName) && numWaits < maxWaits) {
			numWaits++;
			AbstractGTest.sleep(waitTime);
		}

		AbstractGuiTest.waitForSwing();
		bool success = desiredProjectName.equals(lastOpenedProjectName);
		if (!success) {
			Msg.info(typeof(SharedProjectUtil),
				"\tOpen windows: " + AbstractDockingTest.getOpenWindowsAsString());
		}

		return success;
	}

	public static bool deleteTestProject(string projectName) {
		File projectDirectory = new File(AbstractGTest.getTestDirectoryPath());

		File dirFile =
			new File(projectDirectory, projectName + ProjectLocator.getProjectDirExtension());

		int count = 0;
		while (dirFile.exists() && count < 500) {
			++count;
			try {
				Thread.sleep(50);
			}
			catch (InterruptedException e) {
				Msg.error(typeof(SharedProjectUtil), e, e);
			}

			AbstractGhidraHeadlessIntegrationTest.deleteProject(projectDirectory.getAbsolutePath(),
				projectName);
		}
		if (count > 500) {
			Msg.warn(typeof(SharedProjectUtil), "Could not delete " + projectName);
			return false;
		}
		return true;
	}

	/**
	 * Note: This should be called with Err's GUI mode disabled.  When you get a FrontEnd
	 * tool from TestEnv, that action turns on the GUI display for showing errors, by default.  
	 * So, you should call this method before accessing any GUI components in the test system. 
	 * If the GUI error display is enabled when this method is invoked, then server 
	 * connection attempts may trigger error dialogs that are considered 'normal' when running
	 * in the test environment.
	 * 
	 * @return the new server adapter 
	 * @throws Exception if there are any exceptions starting the server
	 */
	public static RepositoryAdapter startServer()
    {
		Msg.info(typeof(SharedProjectUtil), "SharedProjectUtil.startServer()...");
		repositoryServer = null;
		File parent = new File(AbstractGTest.getTestDirectoryPath());

		// Create server instance
		serverRoot = new File(parent, "My_Server");
		FileUtilities.deleteDir(serverRoot);

		Msg.info(typeof(SharedProjectUtil),
			"SharedProjectUtil.startServer()\tgetting server adapter...");
		repositoryServer = ServerTestUtil.getServerAdapter(serverRoot, new string[] { USER });

		Msg.info(typeof(SharedProjectUtil),
			"SharedProjectUtil.startServer()\tchecking connection...");
		if (repositoryServer == null || !repositoryServer.isConnected()) {
			deleteServerRoot();
			fail("Server connect failed");
		}

		Msg.info(typeof(SharedProjectUtil),
			"SharedProjectUtil.startServer()\tcreating repository...");
		return repositoryServer.createRepository("My_Repository");
	}

	public static void deleteServerRoot() {
		if (serverRoot != null) {
			ServerTestUtil.disposeServer();
			FileUtilities.deleteDir(serverRoot);
			serverRoot = null;
		}
	}

	public static void createRepository(string repositoryName)
    {
		if (repositoryServer == null) {
			throw new IllegalStateException(
				"startServer() method must be called before a " + "repository can be created!");
		}
		repositoryServer.createRepository(repositoryName);
	}

	private static DockingActionIf getAction(FrontEndTool frontEndTool, string actionName) {

		DockingActionIf action =
			AbstractDockingTest.getAction(frontEndTool, "FrontEndPlugin", actionName);
		return action;
	}

	private static class UtilProjectListener : ProjectListener {

		private string lastOpenedProjectName;

		/* @Override */
		public void projectClosed(Project project) {
			Msg.info(typeof(UtilProjectListener),
				getClass().getSimpleName() + ".projectClosed(): " + project);
		}

		/* @Override */
		public void projectOpened(Project project) {
			Msg.info(typeof(UtilProjectListener),
				getClass().getSimpleName() + ".projectOpened(): " + project);
			lastOpenedProjectName = project.getName();
		}

		string getLastOpenedProjectName() {
			return lastOpenedProjectName;
		}
	}
}
